macro_rules! deps {
    () => {
        Input!();
        Match!();
        Config!();
        DFA!();
        MatchKind!();
        PatternID!();
        Anchored!();
    };
}

macro_rules! impl_65 {
    () => {
        deps!();
        impl Config { # [doc = " Return a new default one-pass DFA configuration."] pub fn new () -> Config { Config :: default () } # [doc = " Set the desired match semantics."] # [doc = ""] # [doc = " The default is [`MatchKind::LeftmostFirst`], which corresponds to the"] # [doc = " match semantics of Perl-like regex engines. That is, when multiple"] # [doc = " patterns would match at the same leftmost position, the pattern that"] # [doc = " appears first in the concrete syntax is chosen."] # [doc = ""] # [doc = " Currently, the only other kind of match semantics supported is"] # [doc = " [`MatchKind::All`]. This corresponds to \"classical DFA\" construction"] # [doc = " where all possible matches are visited."] # [doc = ""] # [doc = " When it comes to the one-pass DFA, it is rarer for preference order and"] # [doc = " \"longest match\" to actually disagree. Since if they did disagree, then"] # [doc = " the regex typically isn't one-pass. For example, searching `Samwise`"] # [doc = " for `Sam|Samwise` will report `Sam` for leftmost-first matching and"] # [doc = " `Samwise` for \"longest match\" or \"all\" matching. However, this regex is"] # [doc = " not one-pass if taken literally. The equivalent regex, `Sam(?:|wise)`"] # [doc = " is one-pass and `Sam|Samwise` may be optimized to it."] # [doc = ""] # [doc = " The other main difference is that \"all\" match semantics don't support"] # [doc = " non-greedy matches. \"All\" match semantics always try to match as much"] # [doc = " as possible."] pub fn match_kind (mut self , kind : MatchKind) -> Config { self . match_kind = Some (kind) ; self } # [doc = " Whether to compile a separate start state for each pattern in the"] # [doc = " one-pass DFA."] # [doc = ""] # [doc = " When enabled, a separate **anchored** start state is added for each"] # [doc = " pattern in the DFA. When this start state is used, then the DFA will"] # [doc = " only search for matches for the pattern specified, even if there are"] # [doc = " other patterns in the DFA."] # [doc = ""] # [doc = " The main downside of this option is that it can potentially increase"] # [doc = " the size of the DFA and/or increase the time it takes to build the DFA."] # [doc = ""] # [doc = " You might want to enable this option when you want to both search for"] # [doc = " anchored matches of any pattern or to search for anchored matches of"] # [doc = " one particular pattern while using the same DFA. (Otherwise, you would"] # [doc = " need to compile a new DFA for each pattern.)"] # [doc = ""] # [doc = " By default this is disabled."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to build a multi-regex and then search for"] # [doc = " matches for a any of the patterns or matches for a specific pattern."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     dfa::onepass::DFA, Anchored, Input, Match, PatternID,"] # [doc = " };"] # [doc = ""] # [doc = " let re = DFA::builder()"] # [doc = "     .configure(DFA::config().starts_for_each_pattern(true))"] # [doc = "     .build_many(&[\"[a-z]+\", \"[0-9]+\"])?;"] # [doc = " let (mut cache, mut caps) = (re.create_cache(), re.create_captures());"] # [doc = " let haystack = \"123abc\";"] # [doc = " let input = Input::new(haystack).anchored(Anchored::Yes);"] # [doc = ""] # [doc = " // A normal multi-pattern search will show pattern 1 matches."] # [doc = " re.try_search(&mut cache, &input, &mut caps)?;"] # [doc = " assert_eq!(Some(Match::must(1, 0..3)), caps.get_match());"] # [doc = ""] # [doc = " // If we only want to report pattern 0 matches, then we'll get no"] # [doc = " // match here."] # [doc = " let input = input.anchored(Anchored::Pattern(PatternID::must(0)));"] # [doc = " re.try_search(&mut cache, &input, &mut caps)?;"] # [doc = " assert_eq!(None, caps.get_match());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn starts_for_each_pattern (mut self , yes : bool) -> Config { self . starts_for_each_pattern = Some (yes) ; self } # [doc = " Whether to attempt to shrink the size of the DFA's alphabet or not."] # [doc = ""] # [doc = " This option is enabled by default and should never be disabled unless"] # [doc = " one is debugging a one-pass DFA."] # [doc = ""] # [doc = " When enabled, the DFA will use a map from all possible bytes to their"] # [doc = " corresponding equivalence class. Each equivalence class represents a"] # [doc = " set of bytes that does not discriminate between a match and a non-match"] # [doc = " in the DFA. For example, the pattern `[ab]+` has at least two"] # [doc = " equivalence classes: a set containing `a` and `b` and a set containing"] # [doc = " every byte except for `a` and `b`. `a` and `b` are in the same"] # [doc = " equivalence class because they never discriminate between a match and a"] # [doc = " non-match."] # [doc = ""] # [doc = " The advantage of this map is that the size of the transition table"] # [doc = " can be reduced drastically from (approximately) `#states * 256 *"] # [doc = " sizeof(StateID)` to `#states * k * sizeof(StateID)` where `k` is the"] # [doc = " number of equivalence classes (rounded up to the nearest power of 2)."] # [doc = " As a result, total space usage can decrease substantially. Moreover,"] # [doc = " since a smaller alphabet is used, DFA compilation becomes faster as"] # [doc = " well."] # [doc = ""] # [doc = " **WARNING:** This is only useful for debugging DFAs. Disabling this"] # [doc = " does not yield any speed advantages. Namely, even when this is"] # [doc = " disabled, a byte class map is still used while searching. The only"] # [doc = " difference is that every byte will be forced into its own distinct"] # [doc = " equivalence class. This is useful for debugging the actual generated"] # [doc = " transitions because it lets one see the transitions defined on actual"] # [doc = " bytes instead of the equivalence classes."] pub fn byte_classes (mut self , yes : bool) -> Config { self . byte_classes = Some (yes) ; self } # [doc = " Set a size limit on the total heap used by a one-pass DFA."] # [doc = ""] # [doc = " This size limit is expressed in bytes and is applied during"] # [doc = " construction of a one-pass DFA. If the DFA's heap usage exceeds"] # [doc = " this configured limit, then construction is stopped and an error is"] # [doc = " returned."] # [doc = ""] # [doc = " The default is no limit."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows a one-pass DFA that fails to build because of"] # [doc = " a configured size limit. This particular example also serves as a"] # [doc = " cautionary tale demonstrating just how big DFAs with large Unicode"] # [doc = " character classes can get."] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::{dfa::onepass::DFA, Match};"] # [doc = ""] # [doc = " // 6MB isn't enough!"] # [doc = " DFA::builder()"] # [doc = "     .configure(DFA::config().size_limit(Some(6_000_000)))"] # [doc = "     .build(r\"\\w{20}\")"] # [doc = "     .unwrap_err();"] # [doc = ""] # [doc = " // ... but 7MB probably is!"] # [doc = " // (Note that DFA sizes aren't necessarily stable between releases.)"] # [doc = " let re = DFA::builder()"] # [doc = "     .configure(DFA::config().size_limit(Some(7_000_000)))"] # [doc = "     .build(r\"\\w{20}\")?;"] # [doc = " let (mut cache, mut caps) = (re.create_cache(), re.create_captures());"] # [doc = " let haystack = \"A\".repeat(20);"] # [doc = " re.captures(&mut cache, &haystack, &mut caps);"] # [doc = " assert_eq!(Some(Match::must(0, 0..20)), caps.get_match());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " While one needs a little more than 3MB to represent `\\w{20}`, it"] # [doc = " turns out that you only need a little more than 4KB to represent"] # [doc = " `(?-u:\\w{20})`. So only use Unicode if you need it!"] pub fn size_limit (mut self , limit : Option < usize >) -> Config { self . size_limit = Some (limit) ; self } # [doc = " Returns the match semantics set in this configuration."] pub fn get_match_kind (& self) -> MatchKind { self . match_kind . unwrap_or (MatchKind :: LeftmostFirst) } # [doc = " Returns whether this configuration has enabled anchored starting states"] # [doc = " for every pattern in the DFA."] pub fn get_starts_for_each_pattern (& self) -> bool { self . starts_for_each_pattern . unwrap_or (false) } # [doc = " Returns whether this configuration has enabled byte classes or not."] # [doc = " This is typically a debugging oriented option, as disabling it confers"] # [doc = " no speed benefit."] pub fn get_byte_classes (& self) -> bool { self . byte_classes . unwrap_or (true) } # [doc = " Returns the DFA size limit of this configuration if one was set."] # [doc = " The size limit is total number of bytes on the heap that a DFA is"] # [doc = " permitted to use. If the DFA exceeds this limit during construction,"] # [doc = " then construction is stopped and an error is returned."] pub fn get_size_limit (& self) -> Option < usize > { self . size_limit . unwrap_or (None) } # [doc = " Overwrite the default configuration such that the options in `o` are"] # [doc = " always used. If an option in `o` is not set, then the corresponding"] # [doc = " option in `self` is used. If it's not set in `self` either, then it"] # [doc = " remains not set."] pub (crate) fn overwrite (& self , o : Config) -> Config { Config { match_kind : o . match_kind . or (self . match_kind) , starts_for_each_pattern : o . starts_for_each_pattern . or (self . starts_for_each_pattern) , byte_classes : o . byte_classes . or (self . byte_classes) , size_limit : o . size_limit . or (self . size_limit) , } } }
    };
}

impl_65!();